&lt;/li&gt;
&lt;li data-local-id=&quot;1ae30aee-0e54-4975-baa4-d79d811c8cbd&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
